import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'app_language.dart';
import 'language_cubit.dart';

class AppLocalizations {
  final AppLanguage language;

  AppLocalizations(this.language);

  static AppLocalizations of(BuildContext context) {
    final lang = context.watch<LanguageCubit>().state;
    return AppLocalizations(lang);
  }

  static String tr(BuildContext context, String key) {
    return of(context).translate(key);
  }

  String translate(String key) {
    final map = _translations[language.code] ?? _translations['en']!;
    return map[key] ?? _translations['en']?[key] ?? key;
  }

  String translateCategory(String? category) {
    if (category == null || category.isEmpty) return translate('cat_other');
    final key = _categoryKeyMap[category.toLowerCase().trim()];
    if (key != null) return translate(key);
    return category;
  }

  String translateUrgency(String? urgency) {
    if (urgency == null || urgency.isEmpty) return translate('urgency_medium');
    final u = urgency.toUpperCase().trim();
    if (u.contains('CRITICAL')) return translate('urgency_critical');
    if (u.contains('HIGH')) return translate('urgency_high');
    if (u.contains('LOW')) return translate('urgency_low');
    return translate('urgency_medium');
  }

  String translateStatus(String? status) {
    if (status == null || status.isEmpty) return translate('status_submitted_badge');
    final s = status.toUpperCase().trim();
    if (s == 'ACCEPTED') return translate('status_accepted_by_uni');
    if (s == 'IN_PROGRESS' || s == 'PROPOSAL' || s == 'PROTOTYPE' || s == 'VALIDATED') return translate('status_in_progress_badge');
    if (s == 'DEPLOYED') return translate('status_deployed_badge');
    if (s == 'DUPLICATE') return translate('status_duplicate_linked');
    if (s == 'CLASSIFIED') return translate('status_classified_badge');
    return translate('status_submitted_badge');
  }

  String translateNotificationTitle(String? title, [String? type]) {
    if (title == null || title.isEmpty) return translate('notifications_title');
    final t = title.toLowerCase();
    if (t.contains('submitted')) {
      final issueTitle = title.contains(':') ? title.split(':').sublist(1).join(':').trim() : '';
      return issueTitle.isNotEmpty 
          ? '${translate('notif_title_problem_submitted')}: $issueTitle'
          : translate('notif_title_problem_submitted');
    }
    if (t.contains('nearby') || type == 'NEARBY_PROBLEM') {
      final issueTitle = title.contains(':') ? title.split(':').sublist(1).join(':').trim() : '';
      return issueTitle.isNotEmpty
          ? '${translate('notif_title_nearby_problem')}: $issueTitle'
          : translate('notif_title_nearby_problem');
    }
    if (t.contains('adopted')) {
      final issueTitle = title.contains(':') ? title.split(':').sublist(1).join(':').trim() : '';
      return issueTitle.isNotEmpty
          ? '${translate('notif_title_uni_adopted')}: $issueTitle'
          : translate('notif_title_uni_adopted');
    }
    if (t.contains('following') || t.contains('followed')) {
      final issueTitle = title.contains(':') ? title.split(':').sublist(1).join(':').trim() : '';
      return issueTitle.isNotEmpty
          ? '${translate('notif_title_following')}: $issueTitle'
          : translate('notif_title_following');
    }
    if (t.contains('status')) {
      final issueTitle = title.contains(':') ? title.split(':').sublist(1).join(':').trim() : '';
      return issueTitle.isNotEmpty
          ? '${translate('notif_title_status_update')}: $issueTitle'
          : translate('notif_title_status_update');
    }
    return title;
  }

  String translateNotificationMessage(String? message, [String? type]) {
    if (message == null || message.isEmpty) return '';
    final m = message.toLowerCase();
    if (m.contains('successfully logged') || m.contains('visible to researchers')) {
      return translate('notif_body_submitted');
    }
    if (m.contains('reported near') || m.contains('tap to view details and upvote')) {
      return translate('notif_body_nearby');
    }
    if (m.contains('you are now following')) {
      return translate('notif_body_following');
    }
    return message;
  }

  String formatTimeAgo(DateTime? date) {
    if (date == null) return translate('time_recently');
    final now = DateTime.now();
    final difference = now.difference(date);
    
    if (difference.inDays > 365) {
      final y = (difference.inDays / 365).floor();
      return '$y ${translate('time_years_ago')}';
    } else if (difference.inDays > 30) {
      final m = (difference.inDays / 30).floor();
      return '$m ${translate('time_months_ago')}';
    } else if (difference.inDays > 0) {
      return '${difference.inDays} ${translate('time_days_ago')}';
    } else if (difference.inHours > 0) {
      return '${difference.inHours} ${translate('time_hours_ago')}';
    } else if (difference.inMinutes > 0) {
      return '${difference.inMinutes} ${translate('time_minutes_ago')}';
    } else {
      return translate('time_just_now');
    }
  }

