extension LocalizationExtension on BuildContext {
  String tr(String key) => AppLocalizations.tr(this, key);
  String trCategory(String? category) => AppLocalizations.of(this).translateCategory(category);
  String trUrgency(String? urgency) => AppLocalizations.of(this).translateUrgency(urgency);
  String trStatus(String? status) => AppLocalizations.of(this).translateStatus(status);
  String formatTimeAgo(DateTime? date) => AppLocalizations.of(this).formatTimeAgo(date);
  String trTimeAgo(DateTime? date) => AppLocalizations.of(this).formatTimeAgo(date);
  String trNotificationTitle(String? title, [String? type]) => AppLocalizations.of(this).translateNotificationTitle(title, type);
  String trNotificationMessage(String? message, [String? type]) => AppLocalizations.of(this).translateNotificationMessage(message, type);
}
